export function bestTemplateForTask(
  task: string,
  extraText = '',
  usedCodes = new Set<string>()
): ServiceTemplate | null {
  const text = (String(task || '') + ' ' + String(extraText || '')).toLowerCase();
  const tokens = text.replace(/[^a-z0-9]+/g, ' ').split(/\s+/).filter((w) => w.length > 2);
  const stop = new Set([
    'the', 'and', 'with', 'from', 'for', 'this', 'that', 'work', 'works',
    'quote', 'customer', 'grout', 'grouting', 'resealing', 'removal',
    'installation', 'premium', 'existing', 'tiles', 'tile'
  ]);
  let best: ServiceTemplate | null = null;
  let bestScore = -1;

  SERVICE_TEMPLATES.forEach((t) => {
    const hay = ((t.code || '') + ' ' + (t.service || '') + ' ' + (t.scope || '')).toLowerCase();
    let score = 0;
    tokens.forEach((w) => {
      if (!stop.has(w) && hay.includes(w)) score += 1;
    });
    if (text.includes('ensuite') && hay.includes('ensuite')) score += 8;
    if ((text.includes('main bathroom') || text.includes('main bath')) && hay.includes('main bathroom')) score += 8;
    if (text.includes('double shower') && hay.includes('double shower')) score += 8;
    if (text.includes('single shower') && hay.includes('single shower')) score += 8;
    if (text.includes('shower base') && hay.includes('shower')) score += 7;
    if (text.includes('repair') && hay.includes('repair')) score += 6;
    if (text.includes('regrout') && hay.includes('regrout')) score += 7;
    if (text.includes('epoxy') && hay.includes('epoxy')) score += 7;
    if (text.includes('polymer') && hay.includes('polymer')) score += 7;
    if (text.includes('floor') && hay.includes('floor')) score += 4;
    if (text.includes('bath') && hay.includes('bath')) score += 3;
    if (text.includes('ceiling') && hay.includes('ceiling')) score += 4;
    if (usedCodes.has(t.code)) score -= 3;
    if (score > bestScore) {
      bestScore = score;
      best = t;
    }
  });

  return bestScore > 0 ? best : null;
}
